def recursive_diff(d1, d2, log=False):
    """
    Recursively compare two dictionaries and log differences if log is True.
    """
    if isinstance(d1, dict) and isinstance(d2, dict):
        diff = {}
        for key in d1.keys() | d2.keys():
            if key in d1 and key in d2:
                if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                    sub_diff = recursive_diff(d1[key], d2[key], log=log)
                    if sub_diff:
                        diff[key] = sub_diff
                elif d1[key] != d2[key]:
                    diff[key] = {'d1': d1[key], 'd2': d2[key]}
            elif key in d1:
                diff[key] = {'d1': d1[key], 'd2': None}
            else:
                diff[key] = {'d1': None, 'd2': d2[key]}

        if log and diff:
            print(f"Differences found: {diff}")

        return diff
    else:
        if log and d1 != d2:
            print(f"Non-dict values differ: d1={d1}, d2={d2}")
        return d1 != d2
