def to_dict(element):
    """Convert an XML element and its children to a dictionary."""
    if len(element) == 0:
        return to_value(element.text)
    return {child.tag: to_dict(child) for child in element}

def to_value(value):
    """Convert an XML text value to the appropriate Python type."""
    if value is None:
        return None
    if value.isdigit():
        return int(value)
    if value.replace('.', '', 1).isdigit():
        return float(value)
    if value.lower() in ['true', 'false']:
        return value.lower() == 'true'
    return value
