        if not re.match(r'^[a-z]+[a-z0-9_]*$', spidercls):
            raise UsageError(f"Spider name must contain only lowercase letters, digits, and underscores: {spider_name}")

        if not opts.template:
            print(f"No template specified, using 'basic' as default")
            opts.template = 'basic'

        if not self._is_valid_template(opts.template):
            raise UsageError(f"Unknown template: {opts.template}")

        if not opts.force and self._spider_exists(spidercls):
            raise UsageError(f"Spider {spidercls} already exists in project, use --force to overwrite")

        self._genspider(spidercls, domain, opts.template)

    def _genspider(self, spidercls, domain, template):
        spider_file = f"{spidercls}.py"
        template_file = self._find_template(template)
        render_templatefile(template_file, spider_file,
                            **{'name': spidercls, 'domain': domain, 'version': __version__})

    def _list_templates(self):
        templates_dir = self._get_templates_dir()
        return [os.path.splitext(os.path.basename(f))[0] for f in glob.glob(os.path.join(templates_dir, '*.tmpl'))]

    def _is_valid_template(self, template):
        return template in self._list_templates()

    def _spider_exists(self, spidercls):
        spiders_dir = self.settings.get('SPIDER_MODULES')[0].replace('.', os.sep)
        spider_file = os.path.join(spiders_dir, f"{spidercls}.py")
        return os.path.exists(spider_file)

    def _get_templates_dir(self):
        return os.path.join(os.path.dirname(__file__), '..', 'templates', 'spiders')
